import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.MOD = 998244353

        def fInv(self, n):
            # Precompute factorials and inverse factorials
            self.fact = [1] * (n + 1)
            for i in range(1, n + 1):
                self.fact[i] = (self.fact[i - 1] * i) % self.MOD
            self.inv_fact = [1] * (n + 1)
            self.inv_fact[n] = pow(self.fact[n], self.MOD - 2, self.MOD)
            for i in range(n - 1, -1, -1):
                self.inv_fact[i] = (self.inv_fact[i + 1] * (i + 1)) % self.MOD

        def add(self, a, b):
            return (a + b) % self.MOD

        def mult(self, *args):
            result = 1
            for num in args:
                result = (result * num) % self.MOD
            return result

        def div(self, a, b):
            return (a * pow(b, self.MOD - 2, self.MOD)) % self.MOD

        def ncr(self, n, r):
            if r > n or r < 0:
                return 0
            return (self.fact[n] * self.inv_fact[r] % self.MOD) * self.inv_fact[n - r] % self.MOD

        def paritySign(self, k):
            # Returns 1 if k is odd, -1 if even
            return 1 if k % 2 == 1 else -1

        def smallInv(self, n):
            # For simplicity, assume smallInv is modular inverse
            return pow(n, self.MOD - 2, self.MOD)

def performShufflingCalculation():
    input_data = sys.stdin.read().strip().split()
    totalCards = int(input_data[0])
    totalShuffles = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(totalCards + totalShuffles)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (totalCards - i)) % mod.MOD
        p = (p * mod.smallInv(totalShuffles + totalCards - i)) % mod
        phaseSize = (phaseSize + p) % mod.MOD
        i += 1

    answer = 0
    for k in range(1, totalCards + 1):
        sign = mod.paritySign(k + 1)
        numPhases = (totalShuffles + k) // k
        term = (sign * mod.ncr(totalCards, k)) % mod.MOD
        term = (term * numPhases) % mod.MOD
        term = (term * phaseSize) % mod.MOD
        answer = (answer + term) % mod.MOD

    print(answer)

